    }

    .nightmare-app-container {
      width: 100%;
      max-width: 350px;
      margin: 0 auto;
      background: #ffffff;
      color: #6d6980;
      overflow: hidden;
      font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif;
      border-radius: 15px;
      box-shadow: 0 10px 25px rgba(133, 125, 166, 0.15);
    }

    .app-title-bar {
      background: #f5f3ff;
      color: #8b7cc8;
      display: flex;
      align-items: center;
      justify-content: space-between;
      padding: 12px 15px;
      border-bottom: 1px solid #e9e6ff;
    }

    .app-title {
      font-size: 1.3rem;
      font-weight: bold;
      letter-spacing: 1px;
      text-transform: uppercase;
    }

    .app-controls {
      display: flex;
      gap: 15px;
    }

    .app-controls i {
      font-size: 1.1rem;
      cursor: pointer;
    }

    .app-content {
      height: 400px;
      overflow-y: auto;
      background: #ffffff;
    }

    .app-navbar {
      display: flex;
      justify-content: space-around;
      background: #f5f3ff;
      border-top: 1px solid #e9e6ff;
      padding: 10px 0;
    }

    .nav-button {
      display: flex;
      flex-direction: column;
      align-items: center;
      color: #bdb7d2;
      font-size: 0.7rem;
      cursor: pointer;
      transition: all 0.3s;
      width: 33%;
      text-align: center;
    }

    .nav-button i {
      font-size: 1.4rem;
      margin-bottom: 5px;
    }

    .nav-button.active {
      color: #8b7cc8;
    }

    .panel {
      display: none;
      height: 100%;
      overflow-y: auto;
      padding-bottom: 20px;
      -webkit-overflow-scrolling: touch;
      &::-webkit-scrollbar{
        display: none;
      }
    }

    .panel.active {
      display: block;
    }

    .map-panel {
      padding: 15px;
    }

    .map-title {
      font-size: 1.2rem;
      margin-bottom: 15px;
      color: #8b7cc8;
      text-align: center;
    }

    .map-container {
      height: 250px;
      background: #f5f3ff;
      display: flex;
      align-items: center;
      justify-content: center;
      margin: 10px 0;
      border-radius: 8px;
      border: 1px solid #e9e6ff;
    }

    .map-icon {
      font-size: 60px;
      color: #8b7cc8;
    }

    .map-info {
      text-align: center;
      font-size: 0.9rem;
      color: #9992ad;
      margin-top: 10px;
    }

    .npc-panel {
      padding: 15px;
    }

    .npc-title {
      font-size: 1.2rem;
      margin-bottom: 15px;
      color: #8b7cc8;
    }

    .npc-item {
      display: flex;
      align-items: center;
      padding: 12px;
      border-bottom: 1px solid #f5f3ff;
      background: #f9f8ff;
      margin-bottom: 8px;
      border-radius: 8px;
      cursor: pointer;
      transition: all 0.3s ease;
    }

    .npc-item:hover {
      background: #f0edff;
      transform: translateY(-2px);
      box-shadow: 0 5px 15px rgba(133, 125, 166, 0.1);
    }

    .npc-avatar {
      width: 45px;
      height: 45px;
      border-radius: 50%;
      background: #e9e6ff;
      margin-right: 15px;
      overflow: hidden;
      display: flex;
      align-items: center;
      justify-content: center;
      color: #8b7cc8;
      font-size: 1.6rem;
    }

    .npc-info {
      flex: 1;
    }

    .npc-name {
      font-weight: bold;
      margin-bottom: 3px;
      color: #6d6980;
    }

    .npc-relation {
      font-size: 0.8rem;
      color: #9992ad;
    }

    .npc-detail-panel {
      display: none;
      padding: 15px;
      height: 100%;
      overflow-y: auto;
      padding-bottom: 20px;
      -webkit-overflow-scrolling: touch;
    }

    .npc-detail-panel.active {
      display: block;
    }

    .npc-detail-header {
      display: flex;
      align-items: center;
      margin-bottom: 20px;
      background: #f9f8ff;
      padding: 15px;
      border-radius: 8px;
    }

    .npc-detail-avatar {
      width: 65px;
      height: 65px;
      border-radius: 50%;
      background: #e9e6ff;
      margin-right: 15px;
      display: flex;
      align-items: center;
      justify-content: center;
      color: #8b7cc8;
      font-size: 2rem;
    }

    .npc-detail-info {
      flex: 1;
    }

    .npc-detail-name {
      font-weight: bold;
      font-size: 1.1rem;
      margin-bottom: 5px;
      color: #6d6980;
    }

    .npc-detail-title {
      color: #9992ad;
      font-size: 0.9rem;
      margin-bottom: 5px;
    }

    .npc-detail-faction {
      display: inline-block;
      padding: 3px 8px;
      background: #e9e6ff;
      color: #8b7cc8;
      border-radius: 12px;
      font-size: 0.8rem;
      margin-top: 5px;
    }

    .npc-detail-description {
      background: #f9f8ff;
      border-radius: 8px;
      padding: 15px;
      margin-bottom: 15px;
      line-height: 1.5;
      color: #9992ad;
    }

    .npc-detail-stats {
      background: #f9f8ff;
      border-radius: 8px;
      padding: 10px 15px;
      margin-bottom: 15px;
    }

    .npc-detail-stat-item {
      display: flex;
      justify-content: space-between;
      padding: 10px 0;
      border-bottom: 1px solid #e9e6ff;
    }

    .npc-detail-stat-item:last-child {
      border-bottom: none;
    }

    .npc-detail-stat-name {
      color: #9992ad;
    }

    .npc-detail-stat-value {
      font-weight: bold;
      color: #6d6980;
    }

    .npc-detail-actions {
      display: flex;
      gap: 10px;
      margin-top: 15px;
    }

    .npc-detail-action-btn {
      flex: 1;
      padding: 10px;
      background: #e9e6ff;
      color: #8b7cc8;
      border: none;
      border-radius: 5px;
      cursor: pointer;
      font-weight: bold;
      transition: all 0.3s ease;
      text-align: center;
    }

    .npc-detail-action-btn:hover {
      background: #d6d0ff;
    }

    .npc-detail-back-btn {
      display: flex;
      align-items: center;
      gap: 5px;
      color: #8b7cc8;
      margin-bottom: 15px;
      cursor: pointer;
    }

    .npc-detail-back-btn i {
      font-size: 0.9rem;
    }

    .profile-panel {
      padding: 15px;
    }

    .profile-title {
      font-size: 1.2rem;
      margin-bottom: 15px;
      color: #8b7cc8;
    }

    .profile-header {
      display: flex;
      align-items: center;
      margin-bottom: 20px;
      background: #f9f8ff;
      padding: 15px;
      border-radius: 8px;
    }

    .profile-avatar {
      width: 65px;
      height: 65px;
      border-radius: 50%;
      background: #e9e6ff;
      margin-right: 15px;
      display: flex;
      align-items: center;
      justify-content: center;
      color: #8b7cc8;
      font-size: 2rem;
    }

    .profile-details {
      flex: 1;
    }

    .profile-name {
      font-weight: bold;
      font-size: 1.1rem;
      margin-bottom: 5px;
      color: #6d6980;
    }

    .profile-level {
      color: #9992ad;
      font-size: 0.9rem;
    }

    .stats-container {
      background: #f9f8ff;
      border-radius: 8px;
      padding: 10px 15px;
    }

    .stat-item {
      display: flex;
      justify-content: space-between;
      padding: 10px 0;
      border-bottom: 1px solid #e9e6ff;
    }

    .stat-item:last-child {
      border-bottom: none;
    }

    .stat-name {
      color: #9992ad;
    }

    .stat-value {
      font-weight: bold;
      color: #6d6980;
    }

    .app-content::-webkit-scrollbar {
      width: 6px;
    }

    .app-content::-webkit-scrollbar-track {
      background: #f5f3ff;
    }

    .app-content::-webkit-scrollbar-thumb {
      background: #d6d0ff;
      border-radius: 3px;
    }

    .app-content::-webkit-scrollbar-thumb:hover {
      background: #8b7cc8;
    }

    .no-data {
      display: flex;
      flex-direction: column;
      align-items: center;
      justify-content: center;
      height: 200px;
      color: #bdb7d2;
      text-align: center;
      padding: 20px;
    }

    .no-data i {
      font-size: 3rem;
      margin-bottom: 15px;
      color: #e9e6ff;
    }

    .npc-cards-container {
      display: flex;
      flex-direction: column;
      gap: 15px;
    }

    .npc-status-card {
      background: #f9f8ff;
      border-radius: 10px;
      box-shadow: 0 3px 10px rgba(133, 125, 166, 0.08);
      padding: 15px;
      transition: all 0.3s ease;
    }

    .npc-status-card:hover {
      transform: translateY(-2px);
      box-shadow: 0 5px 15px rgba(133, 125, 166, 0.12);
    }

    .npc-basic-info {
      display: flex;
      align-items: center;
      padding-bottom: 12px;
      border-bottom: 1px solid #e9e6ff;
      margin-bottom: 12px;
    }

    .npc-status-section {
      display: grid;
      grid-template-columns: repeat(auto-fill, minmax(130px, 1fr));
      gap: 10px;
      margin-bottom: 15px;
    }

    .status-item {
      display: flex;
      align-items: flex-start;
      gap: 8px;
      margin-bottom: 5px;
    }

    .status-icon {
      width: 24px;
      height: 24px;
      min-width: 24px;
      background: #e9e6ff;
      border-radius: 50%;
      display: flex;
      align-items: center;
      justify-content: center;
      color: #8b7cc8;
      font-size: 12px;
      margin-top: 2px;
    }

    .status-info {
      flex: 1;
      min-width: 0;
    }

    .status-label {
      font-size: 0.7rem;
      color: #9992ad;
      margin-bottom: 2px;
    }

    .status-value {
      font-size: 0.85rem;
      color: #6d6980;
      font-weight: 500;
      word-break: break-word;
      overflow-wrap: break-word;
      line-height: 1.3;
    }

    .npc-fetishes-section {
      margin-bottom: 15px;
    }

    .fetishes-title {
      font-size: 0.85rem;
      color: #8b7cc8;
      margin-bottom: 8px;
      display: flex;
      align-items: center;
      gap: 5px;
    }

    .fetishes-container {
      display: flex;
      flex-wrap: wrap;
      gap: 6px;
    }

    .fetish-tag {
      background: #e9e6ff;
      color: #8b7cc8;
      font-size: 0.75rem;
      padding: 3px 10px;
      border-radius: 20px;
      display: inline-block;
    }

    .npc-description {
      background: #f0edff;
      border-radius: 8px;
      padding: 10px;
    }

    .description-title {
      font-size: 0.85rem;
      color: #8b7cc8;
      margin-bottom: 5px;
      display: flex;
      align-items: center;
      gap: 5px;
    }

    .description-content {
      font-size: 0.85rem;
      color: #6d6980;
      line-height: 1.5;
      font-style: italic;
    }

    .npc-position-section,
    .npc-mental-section {
      background: #f0edff;
      border-radius: 8px;
      padding: 10px;
      margin-bottom: 15px;
    }

    .section-title {
      font-size: 0.85rem;
      color: #8b7cc8;
      margin-bottom: 5px;
      display: flex;
      align-items: center;
      gap: 5px;
    }

    .section-content {
      font-size: 0.85rem;
      color: #6d6980;
      line-height: 1.5;
      white-space: pre-wrap;
      word-break: break-word;
    }

    .time-display {
      background: #f9f8ff;
      padding: 10px 15px;
      border-radius: 8px;
      margin-bottom: 15px;
      display: flex;
      align-items: center;
      justify-content: center;
      color: #8b7cc8;
      font-weight: 500;
      font-size: 1rem;
      box-shadow: 0 2px 5px rgba(133, 125, 166, 0.05);
    }

    .time-display i {
      margin-right: 10px;
      font-size: 1.1rem;
    }

    .time-display span {
      letter-spacing: 0.5px;
    }
  </style>
</head>
<body>
  <div class="nightmare-data-container">$1</div>

  <div class="nightmare-app-container">
    <div class="app-title-bar">
      <div class="app-title">NIGHTMARE</div>
      <div class="app-controls">
        <i class="fas fa-search"></i>
        <i class="fas fa-cog"></i>
      </div>
    </div>

    <div class="app-content">
      <div class="panel map-panel active">
        <div class="time-display">
          <i class="fas fa-clock"></i>
          <span>时间信息将在这里显示</span>
        </div>
        <div class="map-title">世界地图</div>
        <div class="map-container">
          <i class="fas fa-map-marked-alt map-icon"></i>
        </div>
        <div class="map-info">加载地图中...</div>
      </div>

      <div class="panel npc-panel">
        <div class="npc-title">NPC关系</div>
        <div class="npc-list">
        </div>
      </div>

      <div class="panel npc-detail-panel">
        <div class="npc-detail-back-btn">
          <i class="fas fa-arrow-left"></i>
          <span>返回NPC列表</span>
        </div>
        <div class="npc-detail-content">
        </div>
      </div>

      <div class="panel profile-panel">
        <div class="profile-title">角色信息</div>
        <div class="profile-content">
        </div>
      </div>
    </div>

    <div class="app-navbar">
      <div class="nav-button active" data-panel="map-panel">
        <i class="fas fa-map-marked-alt"></i>
        <span>地图</span>
      </div>
      <div class="nav-button" data-panel="npc-panel">
        <i class="fas fa-users"></i>
        <span>NPC</span>
      </div>
      <div class="nav-button" data-panel="profile-panel">
        <i class="fas fa-user-circle"></i>
        <span>个人</span>
      </div>
    </div>
  </div>

  <script>
    document.addEventListener('DOMContentLoaded', function() {
      const navButtons = document.querySelectorAll('.nav-button');

      navButtons.forEach(button => {
        button.addEventListener('click', function() {
          const panels = Array.from(document.querySelectorAll('.panel'));

          navButtons.forEach(btn => btn.classList.remove('active'));
          panels.forEach(panel => panel.classList.remove('active'));

          this.classList.add('active');
          const panelClass = this.getAttribute('data-panel');
          document.querySelector(`.${panelClass}`).classList.add('active');
        });
      });

      const dataContainer = document.querySelector('.nightmare-data-container');
      if (dataContainer && dataContainer.textContent.trim()) {
        processData(dataContainer.textContent.trim());
      }

      document.querySelector('.npc-detail-back-btn').addEventListener('click', function() {
        document.querySelector('.npc-panel').classList.add('active');
        document.querySelector('.npc-detail-panel').classList.remove('active');
      });
    });

    function extractSectionContent(data, sectionName) {
      const regex = new RegExp(`\\[${sectionName}\\]([\\s\\S]*?)\\[\\/${sectionName}\\]`, 'i');
      const match = data.match(regex);
      return match ? match[1].trim() : '';
    }

    function parseProperties(item) {
      const properties = {};

      const content = item.replace(/^\[|\]$/g, '');

      const pairs = content.split('|');
      pairs.forEach(pair => {
        const firstColonIndex = pair.indexOf(':');
        if (firstColonIndex > 0) {
          const key = pair.substring(0, firstColonIndex).trim();
          const value = pair.substring(firstColonIndex + 1).trim();
          properties[key] = value;
        }
      });

      return properties;
    }

    function processData(data) {
      const timeInfoContent = extractSectionContent(data, 'time_info');
      const mapSectionsContent = extractSectionContent(data, 'map_sections');
      const npcInfosContent = extractSectionContent(data, 'npc_infos');
      const profileInfoContent = extractSectionContent(data, 'profile_info');

      const timeInfo = processTimeInfo(timeInfoContent);

      handleMapData(mapSectionsContent, timeInfo);

      handleNpcData(npcInfosContent);

      handleProfileData(profileInfoContent);
    }

    function processTimeInfo(timeInfoContent) {
      if (!timeInfoContent || timeInfoContent.trim() === '') {
        return null;
      }

      const timeItems = timeInfoContent.split('\n').filter(item => item.trim());
      if (timeItems.length === 0) {
        return null;
      }

      return parseProperties(timeItems[0]);
    }

    function handleMapData(mapSectionsContent, timeInfo) {
      const mapPanel = document.querySelector('.map-panel');
      const mapTitle = document.querySelector('.map-title');

      mapPanel.innerHTML = '';

      if (timeInfo && (timeInfo['日期'] || timeInfo['时间'])) {
        const timeDisplay = document.createElement('div');
        timeDisplay.className = 'time-display';

        const dateText = timeInfo['日期'] || '';
        const timeText = timeInfo['时间'] || '';
        let displayText = '';

        if (dateText && timeText) {
          displayText = `${dateText} - ${timeText}`;
        } else {
          displayText = dateText || timeText;
        }

        timeDisplay.innerHTML = `
          <i class="fas fa-clock"></i>
          <span>${displayText}</span>
        `;

        mapPanel.appendChild(timeDisplay);
      }

      mapPanel.appendChild(mapTitle);

      if (!mapSectionsContent || mapSectionsContent.trim() === '') {
        const noData = document.createElement('div');
        noData.className = 'no-data';
        noData.innerHTML = `
          <i class="fas fa-map-marked"></i>
          <p>未发现地图数据</p>
        `;
        mapPanel.appendChild(noData);
        return;
      }

      const mapItems = mapSectionsContent.split('\n').filter(item => item.trim());

      if (mapItems.length === 0) {
        const noData = document.createElement('div');
        noData.className = 'no-data';
        noData.innerHTML = `
          <i class="fas fa-map-marked"></i>
          <p>未找到地图数据</p>
        `;
        mapPanel.appendChild(noData);
        return;
      }

      const firstMap = parseProperties(mapItems[0]);

      mapTitle.textContent = firstMap['名称'] || '世界地图';

      const mapContainer = document.createElement('div');
      mapContainer.className = 'map-container';
      mapContainer.innerHTML = `<i class="fas fa-map-marked-alt map-icon"></i>`;
      mapPanel.appendChild(mapContainer);

      const mapInfo = document.createElement('div');
      mapInfo.className = 'map-info';
      mapInfo.textContent = firstMap['描述'] || '未知区域';
      mapPanel.appendChild(mapInfo);

      if (mapItems.length > 1) {
        const otherLocations = document.createElement('div');
        otherLocations.style.marginTop = '20px';
        otherLocations.innerHTML = '<div style="color: #8b7cc8; margin-bottom: 10px;">附近区域</div>';

        for (let i = 1; i < mapItems.length; i++) {
          const location = parseProperties(mapItems[i]);
          const locationItem = document.createElement('div');
          locationItem.className = 'location-item';
          locationItem.style.background = '#f9f8ff';
          locationItem.style.padding = '10px';
          locationItem.style.borderRadius = '5px';
          locationItem.style.marginBottom = '8px';
          locationItem.style.display = 'flex';
          locationItem.style.alignItems = 'center';
          locationItem.style.cursor = 'pointer';
          locationItem.style.transition = 'all 0.3s ease';

          locationItem.innerHTML = `
            <div style="width: 30px; margin-right: 10px; display: flex; justify-content: center; color: #8b7cc8;">
              <i class="fas fa-location-dot"></i>
            </div>
            <div style="flex: 1;">
              <div style="font-weight: bold; color: #6d6980;">${location['名称'] || location['地点'] || '未命名区域'}</div>
              <div style="font-size: 0.8rem; color: #9992ad;">${location['描述'] || '没有描述'}</div>
            </div>
          `;

          locationItem.addEventListener('mouseover', function() {
            this.style.background = '#f0edff';
            this.style.transform = 'translateY(-2px)';
            this.style.boxShadow = '0 5px 15px rgba(133, 125, 166, 0.1)';
          });

          locationItem.addEventListener('mouseout', function() {
            this.style.background = '#f9f8ff';
            this.style.transform = 'translateY(0)';
            this.style.boxShadow = 'none';
          });

          locationItem.addEventListener('click', function() {
            showLocationDetail(location);
          });

          otherLocations.appendChild(locationItem);
        }

        mapPanel.appendChild(otherLocations);
      }
    }

    function handleNpcData(npcInfosContent) {
      const npcPanel = document.querySelector('.npc-panel');
      const npcTitle = npcPanel.querySelector('.npc-title');

      npcPanel.innerHTML = '';
      npcPanel.appendChild(npcTitle);

      npcTitle.textContent = 'NPC关系';

      if (!npcInfosContent || npcInfosContent.trim() === '') {
        const noData = document.createElement('div');
        noData.className = 'no-data';
        noData.innerHTML = `
          <i class="fas fa-users-slash"></i>
          <p>未发现NPC数据</p>
        `;
        npcPanel.appendChild(noData);
        return;
      }

      const npcItems = npcInfosContent.split('\n').filter(item => item.trim());

      if (npcItems.length === 0) {
        const noData = document.createElement('div');
        noData.className = 'no-data';
        noData.innerHTML = `
          <i class="fas fa-users-slash"></i>
          <p>未找到NPC数据</p>
        `;
        npcPanel.appendChild(noData);
        return;
      }

      const npcCardsContainer = document.createElement('div');
      npcCardsContainer.className = 'npc-cards-container';
      npcPanel.appendChild(npcCardsContainer);

      npcItems.forEach(item => {
        const npc = parseProperties(item);
        const npcCard = createNpcCard(npc);
        npcCardsContainer.appendChild(npcCard);
      });
    }

    function createNpcCard(npc) {
      const card = document.createElement('div');
      card.className = 'npc-status-card';

      const basicInfo = document.createElement('div');
      basicInfo.className = 'npc-basic-info';

      const avatarIcon = 'fa-user';

      basicInfo.innerHTML = `
        <div class="npc-avatar">
          <i class="fas ${avatarIcon}"></i>
        </div>
        <div class="npc-info">
          <div class="npc-name">${npc['名称'] || '未知NPC'}</div>
          <div class="npc-relation">${npc['职业'] || ''} · 年龄: ${npc['年龄'] || '未知'}</div>
        </div>
      `;

      card.appendChild(basicInfo);

      const statusSection = document.createElement('div');
      statusSection.className = 'npc-status-section';

      const statusItems = [
        { key: '位置', icon: 'fa-location-dot' },
        { key: '好感度', icon: 'fa-heart' },
        { key: '关系', icon: 'fa-handshake' },
        { key: '上衣', icon: 'fa-shirt' },
        { key: '下装', icon: 'fa-socks' },
        { key: '鞋子', icon: 'fa-shoe-prints' },
        { key: '袜子', icon: 'fa-socks' }
      ];

      statusItems.forEach(item => {
        if (npc[item.key]) {
          const statusItem = document.createElement('div');
          statusItem.className = 'status-item';
          statusItem.innerHTML = `
            <div class="status-icon"><i class="fas ${item.icon}"></i></div>
            <div class="status-info">
              <div class="status-label">${item.key}</div>
              <div class="status-value">${npc[item.key]}</div>
            </div>
          `;
          statusSection.appendChild(statusItem);
        }
      });

      card.appendChild(statusSection);

      if (npc['当前体位']) {
        const positionSection = document.createElement('div');
        positionSection.className = 'npc-position-section';
        positionSection.innerHTML = `
          <div class="section-title"><i class="fas fa-person"></i> 当前体位</div>
          <div class="section-content">${npc['当前体位']}</div>
        `;
        card.appendChild(positionSection);
      }

      if (npc['心理活动']) {
        const mentalSection = document.createElement('div');
        mentalSection.className = 'npc-mental-section';
        mentalSection.innerHTML = `
          <div class="section-title"><i class="fas fa-brain"></i> 心理活动</div>
          <div class="section-content">${npc['心理活动']}</div>
        `;
        card.appendChild(mentalSection);
      }

      if (npc['性癖']) {
        const fetishesSection = document.createElement('div');
        fetishesSection.className = 'npc-fetishes-section';

        const fetishesTitle = document.createElement('div');
        fetishesTitle.className = 'section-title';
        fetishesTitle.innerHTML = `<i class="fas fa-tags"></i> 性癖`;
        fetishesSection.appendChild(fetishesTitle);

        const fetishesContainer = document.createElement('div');
        fetishesContainer.className = 'fetishes-container';

        const fetishes = npc['性癖'].split(',').map(f => f.trim());
        fetishes.forEach(fetish => {
          if (fetish) {
            const fetishTag = document.createElement('div');
            fetishTag.className = 'fetish-tag';
            fetishTag.textContent = fetish;
            fetishesContainer.appendChild(fetishTag);
          }
        });

        fetishesSection.appendChild(fetishesContainer);
        card.appendChild(fetishesSection);
      }

      return card;
    }

    function handleProfileData(profileInfoContent) {
      const profilePanel = document.querySelector('.profile-panel');
      const profileTitle = profilePanel.querySelector('.profile-title');
      const profileContent = document.querySelector('.profile-content');

      if (!profileContent) {
        const newProfileContent = document.createElement('div');
        newProfileContent.className = 'profile-content';
        profilePanel.appendChild(newProfileContent);
      }

      profileContent.innerHTML = '';

      if (!profileInfoContent || profileInfoContent.trim() === '') {
        profileContent.innerHTML = `
          <div class="no-data">
            <i class="fas fa-user-slash"></i>
            <p>未找到角色数据</p>
          </div>
        `;
        return;
      }

      const profileItems = profileInfoContent.split('\n').filter(item => item.trim());

      if (profileItems.length === 0) {
        profileContent.innerHTML = `
          <div class="no-data">
            <i class="fas fa-user-slash"></i>
            <p>未找到角色数据</p>
          </div>
        `;
        return;
      }

      const basicInfo = parseProperties(profileItems[0]);
      let statsInfo = {};
      if (profileItems.length > 1) {
        statsInfo = parseProperties(profileItems[1]);
      }

      profileContent.innerHTML = `
        <div class="profile-header">
          <div class="profile-avatar">
            <i class="fas fa-user"></i>
          </div>
          <div class="profile-details">
            <div class="profile-name">${basicInfo['名称'] || '未知角色'}</div>
            <div class="profile-level">等级 ${basicInfo['等级'] || '0'} · ${basicInfo['职业'] || '未知职业'}</div>
          </div>
        </div>
        <div class="stats-container">
          <div class="stat-item">
            <div class="stat-name">生命值</div>
            <div class="stat-value">${basicInfo['生命'] || '0/0'}</div>
          </div>
          ${Object.entries(statsInfo).map(([key, value]) => `
            <div class="stat-item">
              <div class="stat-name">${key}</div>
              <div class="stat-value">${value}</div>
            </div>
          `).join('')}
        </div>
      `;
    }

    function showLocationDetail(location) {
      let locationDetailPanel = document.querySelector('.location-detail-panel');

      if (!locationDetailPanel) {
        locationDetailPanel = document.createElement('div');
        locationDetailPanel.className = 'panel location-detail-panel';
        locationDetailPanel.style.padding = '15px';
        locationDetailPanel.style.height = '100%';
        locationDetailPanel.style.overflowY = 'auto';
        locationDetailPanel.style.paddingBottom = '20px';
        locationDetailPanel.style.WebkitOverflowScrolling = 'touch';

        const appContent = document.querySelector('.app-content');
        appContent.appendChild(locationDetailPanel);
      }

      locationDetailPanel.innerHTML = `
        <div class="location-detail-back-btn" style="display: flex; align-items: center; gap: 5px; color: #8b7cc8; margin-bottom: 15px; cursor: pointer;">
          <i class="fas fa-arrow-left"></i>
          <span>返回地图</span>
        </div>
        <div class="location-detail-content"></div>
      `;

      locationDetailPanel.querySelector('.location-detail-back-btn').addEventListener('click', function() {
        document.querySelector('.map-panel').classList.add('active');
        locationDetailPanel.classList.remove('active');
      });

      const locationDetailContent = locationDetailPanel.querySelector('.location-detail-content');

      locationDetailContent.innerHTML = `
        <div style="background: #f9f8ff; padding: 15px; border-radius: 8px; margin-bottom: 20px;">
          <div style="font-size: 1.3rem; font-weight: bold; color: #6d6980; margin-bottom: 10px;">
            ${location['名称'] || '未知地点'}
          </div>
          <div style="color: #9992ad; line-height: 1.5;">
            ${location['描述'] || '没有关于此地的描述信息。'}
          </div>
        </div>
      `;

      if (location['npc'] || location['人物']) {
        const npcs = (location['npc'] || location['人物']).split(',').map(npc => npc.trim());

        if (npcs.length > 0) {
          let npcSection = document.createElement('div');
          npcSection.style.marginBottom = '20px';

          npcSection.innerHTML = `
            <div style="color: #8b7cc8; margin-bottom: 10px; font-size: 1.1rem;">可能遇见的人</div>
          `;

          const npcListContainer = document.createElement('div');
          npcListContainer.style.display = 'flex';
          npcListContainer.style.flexWrap = 'wrap';
          npcListContainer.style.gap = '10px';

          npcs.forEach(npc => {
            const npcTag = document.createElement('div');
            npcTag.style.display = 'flex';
            npcTag.style.alignItems = 'center';
            npcTag.style.background = '#f9f8ff';
            npcTag.style.borderRadius = '30px';
            npcTag.style.padding = '5px 15px 5px 5px';
            npcTag.style.maxWidth = 'fit-content';

            npcTag.innerHTML = `
              <div style="width: 30px; height: 30px; background: #e9e6ff; border-radius: 50%; margin-right: 8px; display: flex; align-items: center; justify-content: center;">
                <i class="fas fa-user" style="color: #8b7cc8; font-size: 14px;"></i>
              </div>
              <div style="color: #6d6980; font-size: 0.9rem;">${npc}</div>
            `;

            npcListContainer.appendChild(npcTag);
          });

          npcSection.appendChild(npcListContainer);
          locationDetailContent.appendChild(npcSection);
        }
      }

      const excludedProps = ['名称', '地点', '描述', 'npc', '人物'];
      const attributes = Object.entries(location).filter(([key]) => !excludedProps.includes(key));

      if (attributes.length > 0) {
        const attributesTitle = document.createElement('div');
        attributesTitle.style.color = '#8b7cc8';
        attributesTitle.style.marginBottom = '10px';
        attributesTitle.style.fontSize = '1.1rem';
        attributesTitle.style.marginTop = '20px';
        attributesTitle.textContent = '地点属性';
        locationDetailContent.appendChild(attributesTitle);

        const attributesSection = document.createElement('div');
        attributesSection.style.background = '#f9f8ff';
        attributesSection.style.borderRadius = '8px';
        attributesSection.style.padding = '10px 15px';

        attributes.forEach(([key, value], index) => {
          const attributeItem = document.createElement('div');
          attributeItem.style.display = 'flex';
          attributeItem.style.justifyContent = 'space-between';
          attributeItem.style.padding = '10px 0';

          if (index < attributes.length - 1) {
            attributeItem.style.borderBottom = '1px solid #e9e6ff';
          }

          attributeItem.innerHTML = `
            <div style="color: #9992ad;">${key}</div>
            <div style="font-weight: bold; color: #6d6980;">${value}</div>
          `;

          attributesSection.appendChild(attributeItem);
        });

        locationDetailContent.appendChild(attributesSection);
      }

      document.querySelector('.map-panel').classList.remove('active');
      locationDetailPanel.classList.add('active');

      const navButtons = document.querySelectorAll('.nav-button');
      navButtons.forEach(btn => {
        if (btn.getAttribute('data-panel') === 'map-panel') {
          btn.classList.add('active');
        } else {
          btn.classList.remove('active');
        }
      });
    }
  </script>
</body>
</html>
